python3 << 'EOF'
import csv
from collections import defaultdict

rows = []
with open('/app/benchmark/data.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        rows.append(row)

# More detailed country analysis - normalize "USA" and "United States"
country_norm = {
    'USA': 'USA',
    'United States': 'USA',
    'United States of America': 'USA',
    'PR China': 'China',
    "People's Republic of China": 'China',
    'Republic of Korea': 'South Korea',
    'UK': 'United Kingdom',
    'Jiangxi Province': 'China'
}

def normalize_country(c):
    return country_norm.get(c, c)

normalized_countries = defaultdict(int)
for r in rows:
    c = normalize_country(r['country'])
    normalized_countries[c] += 1

print("Normalized top countries:")
for c, n in sorted(normalized_countries.items(), key=lambda x: -x[1])[:15]:
    print(f"  {c}: {n}")

# Country by year
country_by_year = defaultdict(lambda: defaultdict(int))
for r in rows:
    c = normalize_country(r['country'])
    country_by_year[c][r['pub_year']] += 1

print("\nCountry by year (top 10):")
for c, n in sorted(normalized_countries.items(), key=lambda x: -x[1])[:10]:
    y24 = country_by_year[c]['2024']
    y25 = country_by_year[c]['2025']
    y26 = country_by_year[c]['2026']
    print(f"  {c}: 2024={y24}, 2025={y25}, 2026={y26}")

# Research type by year
rt_by_year = defaultdict(lambda: defaultdict(int))
for r in rows:
    rt = r['research_type']
    if rt:
        for t in rt.split(';'):
            t = t.strip()
            rt_by_year[t][r['pub_year']] += 1

print("\nResearch types by year:")
for t in ['Journal Article', 'Review', 'Case Reports', 'Systematic Review', 'Preprint']:
    y24 = rt_by_year[t]['2024']
    y25 = rt_by_year[t]['2025']
    y26 = rt_by_year[t]['2026']
    print(f"  {t}: 2024={y24}, 2025={y25}, 2026={y26}")

# Author count distribution
author_bins = defaultdict(int)
for r in rows:
    try:
        ac = int(r['authors_count'])
        if ac == 0:
            author_bins['Solo (1)'] += 1
        elif ac == 1:
            author_bins['Solo (1)'] += 1
        elif ac <= 5:
            author_bins['2-5'] += 1
        elif ac <= 10:
            author_bins['6-10'] += 1
        elif ac <= 20:
            author_bins['11-20'] += 1
        else:
            author_bins['20+'] += 1
    except:
        pass

print("\nAuthor count distribution:")
for k, v in sorted(author_bins.items()):
    print(f"  {k}: {v}")

# Journal analysis
journals = defaultdict(int)
for r in rows:
    journals[r['journal']] += 1

print("\nTop journals:")
for j, c in sorted(journals.items(), key=lambda x: -x[1])[:15]:
    print(f"  {j}: {c}")
EOF

